param([string]$RunDate='PLAN-DATE',[ValidateSet('PLAN','EXECUTE')][string]$ExecutionMode='PLAN')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$runner=Join-Path $PSScriptRoot 'run-experiment-1-23-core.ps1';$result=Join-Path $root 'backend\experiments\results\experiment-1-23';$runs=@(@{c='BASELINE';i='001'},@{c='REMEDIATION';i='001'},@{c='BASELINE';i='002'},@{c='REMEDIATION';i='002'},@{c='BASELINE';i='003'},@{c='REMEDIATION';i='003'});New-Item -ItemType Directory -Force (Join-Path $result 'plan')|Out-Null
function Get-ComposeSha([string]$p){(Get-FileHash -LiteralPath (Join-Path $root $p) -Algorithm SHA256).Hash.ToLowerInvariant()}
if($ExecutionMode-eq'PLAN'){
 foreach($r in $runs){& powershell -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $r.c -RunIndex $r.i -RunDate $RunDate -ExecutionMode PLAN;$p=Join-Path $result "plan\$($r.c)-$($r.i)-command-manifest.json";$m=Get-Content $p -Raw|ConvertFrom-Json;$m.composeFiles=@($m.composeFiles|ForEach-Object{[ordered]@{path=if($_.path){$_.path}else{$_};sha256=if($_.sha256){$_.sha256}else{Get-ComposeSha $(if($_.path){$_.path}else{$_})}}});$m|ConvertTo-Json -Depth 20|Set-Content $p -Encoding UTF8}
 $ledger=[ordered]@{experiment='Experiment 1-23';runDate=$RunDate;executionMode='PLAN';requestedRuns=@($runs|ForEach-Object{"$($_.c)-$($_.i)"});startedRuns=0;completedRuns=0;failedRuns=0;notStartedRuns=@($runs|ForEach-Object{"RUN-$RunDate-EXP123-$($_.c)-$($_.i)"});warmupInvocations=0;k6Invocations=0;coreInvocations=0;executionStatus='NOT_RUN'};$ledger|ConvertTo-Json -Depth 10|Set-Content (Join-Path $result 'plan\runner-readiness.json') -Encoding UTF8;Write-Output 'EXP123_PLAN_READY';exit 0}
$failure=$null;foreach($r in $runs){try{& powershell -NoProfile -ExecutionPolicy Bypass -File $runner -Condition $r.c -RunIndex $r.i -RunDate $RunDate -ExecutionMode EXECUTE;if($LASTEXITCODE){throw "core exit $LASTEXITCODE"}}catch{$failure=$_;break}}
$states=@($runs|ForEach-Object{$id="RUN-$RunDate-EXP123-$($_.c)-$($_.i)";$dir=Join-Path $result "core\$id";$warm=Join-Path $root "experiment\results\SMOKE-$RunDate-EXP123-$($_.c)-$($_.i)";[ordered]@{runId=$id;started=Test-Path $dir;completed=Test-Path (Join-Path $dir 'COMPLETED');failed=Test-Path (Join-Path $dir 'EXECUTION_FAILED');warmupInvoked=Test-Path $warm;coreInvoked=Test-Path (Join-Path $dir 'execution-summary.json');k6Invoked=Test-Path (Join-Path $dir 'execution-summary.json')}});$ledger=[ordered]@{experiment='Experiment 1-23';runDate=$RunDate;executionMode='EXECUTE';requestedRuns=@($runs|ForEach-Object{"$($_.c)-$($_.i)"});startedRuns=@($states|Where-Object started).Count;completedRuns=@($states|Where-Object completed).Count;failedRuns=@($states|Where-Object failed).Count;notStartedRuns=@($states|Where-Object{-not$_.started}|ForEach-Object runId);warmupInvocations=@($states|Where-Object warmupInvoked).Count;k6Invocations=@($states|Where-Object k6Invoked).Count;coreInvocations=@($states|Where-Object coreInvoked).Count;executionStatus=if($failure){'FAILED'}elseif(@($states|Where-Object completed).Count-eq6){'COMPLETED'}else{'INCOMPLETE'};runStates=$states};$ledger|ConvertTo-Json -Depth 10|Set-Content (Join-Path $result 'plan\runner-readiness.json') -Encoding UTF8;if($failure){throw $failure}
